86	<script>
87	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
88	// entry (digits being typed, or null), value (the current number).
89	var OPS = {
90	  add: function (a, b) { return a + b; },
91	  sub: function (a, b) { return a - b; },
92	  mul: function (a, b) { return a * b; },
93	  div: function (a, b) { return a / b; }
94	};
95	
96	function initialState() {
97	  return { acc: null, op: null, entry: null, value: 0 };
98	}
99	
100	function press(s, key) {
101	  if (key === 'clear') return initialState();
102	
103	  // After an error, any key except an operator starts over.
104	  if (!isFinite(s.value) && s.entry === null) {
105	    if (key in OPS || key === 'equals') return s;
106	    s = initialState();
107	  }
108	
109	  if (/^[0-9]$/.test(key)) {
110	    var entry = s.entry === null || s.entry === '0' ? key : s.entry + key;
111	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry) };
112	  }
113	
114	  if (key === 'dot') {
115	    var e = s.entry === null ? '0' : s.entry;
116	    if (e.indexOf('.') !== -1) return s;
117	    e += '.';
118	    return { acc: s.acc, op: s.op, entry: e, value: Number(e) };
119	  }
120	
121	  if (key in OPS) {
122	    // Operator right after another operator replaces it.
123	    if (s.op && s.entry === null) return { acc: s.acc, op: key, entry: null, value: s.value };
124	    // Immediate execution: finish the waiting operation first, strictly left to right,
125	    // no precedence. The display always shows a real running result.
126	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
127	    return { acc: v, op: key, entry: null, value: v };
128	  }
129	
130	  if (key === 'equals') {
131	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value };
132	    var r = OPS[s.op](s.acc, s.value);
133	    return { acc: null, op: null, entry: null, value: r };
134	  }
135	
136	  return s;
137	}
138	
139	// Visible text: the entry as typed, or the value rounded to hide float noise.
140	function displayText(s) {
141	  if (s.entry !== null) return s.entry;
142	  if (!isFinite(s.value)) return 'Error';
143	  return String(parseFloat(s.value.toPrecision(12)));
144	}
145	
146	if (typeof document !== 'undefined') {
147	  var state = initialState();
148	  var display = document.querySelector('[data-testid="calc-display"]');
149	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
150	
151	  function render() {
152	    display.textContent = displayText(state);
153	    display.setAttribute('data-value', String(state.value));
154	    for (var i = 0; i < opButtons.length; i++) {
155	      var b = opButtons[i];
156	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null);
157	    }
158	  }
159	
160	  document.querySelector('.keys').addEventListener('click', function (ev) {
161	    var btn = ev.target.closest('button');
162	    if (!btn) return;
163	    state = press(state, btn.dataset.key);
164	    render();
165	  });
166	
167	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
168	    '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
